import { z } from "zod";

import {
  AbstractApplication,
  type IconDescriptor,
  type Interface,
  type InterfacesOf,
} from "../applications/applications";
import { ApplicationId } from "../applications/brett-applications";
import { InterfaceSchema } from "../applications/interfaces";
import { getApplicationDomain } from "../env";
import { OrganizationId } from "../organizations";
import type { RemoteModule } from "../remote-module";
import { ActiveConfig, CONFIG_MODULE_EXPOSE } from "./config";

/**
 * Installation ID schema, branded to keep it distinct from the application id
 * an installation points at.
 * @public
 */
export const InstallationId = z.string().nonempty().brand("InstallationId");

/**
 * Installation ID type, branded for type safety.
 * @public
 */
export type InstallationId = z.output<typeof InstallationId>;

const InstallationSchema = z.object({
  id: InstallationId,
  applicationId: ApplicationId,
  organizationId: OrganizationId,
  application: z.object({
    icon: z.string().nullable(),
    organizationId: OrganizationId,
    title: z.string(),
    name: z.string(),
    reference: z.string(),
    slug: z.string(),
  }),
  access: z.array(
    z.object({ resourceType: z.string(), resourceId: z.string() }),
  ),
  // `null` when requested but nothing is deployed.
  activeConfig: ActiveConfig.nullable().optional(),
  // Present when requested with `include=interfaces`.
  interfaces: z.array(InterfaceSchema).optional(),
});

/**
 * An organization's active installation of a singleton application, as returned
 * from `GET /installations?organizationId=&include=activeConfig,access,interfaces`.
 * @public
 */
export type Installation = z.output<typeof InstallationSchema>;

/**
 * Validates and parses a raw `/installations` record into a branded
 * Installation.
 * @public
 */
export function parseInstalledApplication(data: unknown): Installation {
  return InstallationSchema.parse(data);
}

/**
 * @public
 */
export class InstalledApplication extends AbstractApplication<"installation"> {
  installation: Installation;

  /** A dev server's working config; wins over the deployed one when present. */
  readonly #localConfig: RemoteModule | null;

  constructor(
    installation: Installation,
    localConfig: RemoteModule | null = null,
  ) {
    super("installation");
    this.installation = installation;
    this.#localConfig = localConfig;
  }

  get id(): InstallationId {
    return this.installation.id;
  }

  get title(): string {
    return this.installation.application.title;
  }

  /**
   * Navigable only when it declares an `app` interface — a panel-only
   * installation (e.g. Content Agent) docks a panel but has no full-page view.
   * Derived from the interfaces the same way a core app is.
   */
  override get hasAppView(): boolean {
    return this.interfaces("app").length > 0;
  }

  get href(): string | null {
    if (!this.hasAppView) return null;

    return `/${this.installation.application.slug}`;
  }

  get isFederated(): boolean {
    return true;
  }

  get name(): string {
    return this.installation.application.name;
  }

  get url(): URL {
    return new URL(
      `https://${this.installation.application.slug}-apps-${this.installation.application.organizationId}.${getApplicationDomain()}`,
    );
  }

  get icon(): IconDescriptor {
    const { icon } = this.installation.application;
    if (!icon) {
      return {
        variant: "avatar",
        initials: this.initials,
        color: this.avatarColor,
      };
    }

    return {
      variant: "image",
      svg: icon,
    };
  }

  /**
   * The installation's config as a module ref, or `null` when it has none. A
   * dev server's working copy wins over the deployed one, so a local config can
   * be tried against a real organization.
   */
  get config(): RemoteModule | null {
    if (this.#localConfig) return this.#localConfig;

    const { name } = this.installation.application;
    const { activeConfig, organizationId } = this.installation;
    if (!name || !activeConfig) return null;

    // The deployed config is served at the installation name's stable host —
    // the same stable `name` the local dev-server config binds to.
    return {
      entry: `https://${name}-configs-${organizationId}.${getApplicationDomain()}`,
      moduleId: CONFIG_MODULE_EXPOSE,
      version: activeConfig.version,
    };
  }

  /**
   * Interfaces the installation exposes, read from `include=interfaces` — all of
   * them, or only those of the given `type`. Empty until the fetch requests
   * them. Lights up `resolvedInterfaces` and `moduleId` from the base class, the
   * same way a deployed app's do.
   */
  override interfaces<T extends Interface["type"] | undefined = undefined>(
    type?: T,
  ): InterfacesOf<T> {
    const all = this.installation.interfaces ?? [];
    // The runtime narrows correctly; TS can't tie a `filter` back to the
    // conditional return type, so assert it.
    return (type
      ? all.filter((iface) => iface.type === type)
      : all) as unknown as InterfacesOf<T>;
  }

  get<TKey extends keyof Installation>(attr: TKey): Installation[TKey] {
    if (!(attr in this.installation)) {
      throw new Error(
        `Attribute ${attr.toString()} does not exist on installation ${this.installation.id}`,
      );
    }

    return this.installation[attr];
  }
}
